import json
from urllib.parse import urlparse


def _domain(url):
    try:
        host = urlparse(url).hostname or ""
    except Exception:
        return ""
    return host.lower().removeprefix("www.")


async def run(args, state):
    variables = dict(state.variables) if isinstance(state.variables, dict) else {}
    per_query_limit = int(variables.get("per_query_limit") or 6)
    max_leads = int(variables.get("max_leads") or 25)
    query_count = int(variables.get("query_count") or 6)
    banned = set()
    for raw in variables.get("banned_domains") or []:
        banned.add(str(raw).strip().lower())

    def _banned(url):
        host = _domain(url)
        if not host:
            return True
        for bad in banned:
            if host == bad or host.endswith("." + bad):
                return True
        return False

    queries = []
    raw_response = state.get("response")
    if isinstance(raw_response, str) and raw_response.strip():
        payload = json.loads(raw_response)
        for item in payload.get("queries") or []:
            query = str(item).strip()
            if query:
                queries.append(query)
    for item in variables.get("extra_queries") or []:
        query = str(item).strip()
        if query:
            queries.append(query)
    queries = queries[:query_count]
    if not queries and not state.get("seed_urls"):
        raise ValueError("search_links: нет поисковых запросов")

    errors = list(state.get("node_errors") or [])

    async def _search(query):
        raw = await tools.web_search(
            query=query,
            providers=["auto"],
            provider_strategy="merge",
            language="ru",
            region="ru",
            limit=per_query_limit,
        )
        found = []
        for item in raw.get("results") or []:
            url = str(item.get("url") or "").strip()
            if url:
                found.append(url)
        return found

    flat = []
    for url in state.get("seed_urls") or []:
        flat.append(str(url))
    for query in queries:
        try:
            flat.extend(await _search(query))
        except Exception as exc:
            errors.append("web_search:" + query + ": " + str(exc)[:200])
    if not flat and queries:
        ddg = await tools.browser_duckduckgo_links_batch(
            queries=queries, per_query_limit=per_query_limit
        )
        if isinstance(ddg, dict) and ddg.get("success") is True:
            for url in ddg.get("urls") or []:
                flat.append(str(url))

    seen_domains = set()
    candidate_urls = []
    for url in flat:
        if _banned(url):
            continue
        host = _domain(url)
        if host in seen_domains:
            continue
        seen_domains.add(host)
        candidate_urls.append(url)
        if len(candidate_urls) >= max_leads:
            break

    state["candidate_urls"] = candidate_urls
    state["node_errors"] = errors
    state["search_stats"] = {"queries": queries, "raw_urls": len(flat)}
    return state

