import asyncio
import re
from urllib.parse import urlparse

_LINK_RE = r"\]\((https?://[^)\s]+|/[^)\s]{1,80})"
_CONTACT_HINT = r"contact|kontakt|kontakty|contacts|about|o-nas|o_nas|feedback|svyaz"


def _base(url):
    parsed = urlparse(url)
    return parsed.scheme + "://" + (parsed.hostname or "")


async def run(args, state):
    variables = dict(state.variables) if isinstance(state.variables, dict) else {}
    max_pages = int(variables.get("max_pages") or 12)

    targets = []
    seen = set()
    for url in state.get("candidate_urls") or []:
        base = _base(str(url))
        if base in seen:
            continue
        seen.add(base)
        targets.append(base)

    errors = list(state.get("node_errors") or [])
    spent = 0

    async def _fetch(url):
        try:
            raw = await tools.browser_page_markdown(
                url=url, ingest_source="shop_outreach", max_markdown_chars=20000
            )
        except Exception as exc:
            return {"url": url, "text": "", "error": str(exc)[:200]}
        if not isinstance(raw, dict) or raw.get("success") is not True:
            err = raw.get("error") if isinstance(raw, dict) else "fetch failed"
            return {"url": url, "text": "", "error": str(err)[:200]}
        return {"url": url, "text": str(raw.get("markdown") or "")}

    home_results = await asyncio.gather(*[_fetch(t) for t in targets[:max_pages]])
    spent = len(home_results)
    pages = []
    contact_urls = []
    for page in home_results:
        if page["error"]:
            errors.append("fetch:" + page["url"] + ": " + page["error"])
            continue
        pages.append(page)
        base = _base(page["url"])
        found = 0
        for match in re.finditer(_LINK_RE, page["text"]):
            link = match.group(1)
            if link.startswith("/"):
                link = base + link
            if not link.startswith(base):
                continue
            if not re.search(_CONTACT_HINT, link, re.IGNORECASE):
                continue
            if link.rstrip("/") == base.rstrip("/"):
                continue
            if link not in contact_urls:
                contact_urls.append(link)
                found += 1
                if found >= 2:
                    break

    remaining = max(0, max_pages - spent)
    if remaining and contact_urls:
        contact_results = await asyncio.gather(
            *[_fetch(u) for u in contact_urls[:remaining]]
        )
        for page in contact_results:
            if page["error"]:
                errors.append("fetch:" + page["url"] + ": " + page["error"])
                continue
            pages.append(page)

    state["pages"] = pages
    state["node_errors"] = errors
    return state

