import json
import re
from urllib.parse import urlparse

_EMAIL_RE = r"[A-Za-z0-9._%+\-]+@[A-Za-z0-9.\-]+\.[A-Za-z]{2,}"
_MAILTO_RE = r"mailto:\s*([A-Za-z0-9._%+\-]+@[A-Za-z0-9.\-]+\.[A-Za-z]{2,})"
_OBFUSCATED_RE = (
    r"([A-Za-z0-9._%+\-]{1,64})\s*(?:\[at\]|\(at\)|\s+at\s+|\s+собака\s+)"
    r"\s*([A-Za-z0-9.\-]{2,})\s*(?:\[dot\]|\(dot\)|\s+dot\s+|\s+точка\s+)\s*([A-Za-z]{2,})"
)
_HEADING_RE = r"^#\s+(.{3,80})$"

_BAD_LOCALS = {
    "noreply", "no-reply", "donotreply", "mailer-daemon", "postmaster",
    "hostmaster", "webmaster", "sentry", "wordpress", "example", "test",
    "admin@example", "your-email",
}
_BAD_DOMAIN_PARTS = (
    "sentry", "wixpress", "example.", "localhost", "w3.org", "schema.org",
    "godaddy", "gstatic", "jquery", "bootstrap", "cloudflare", "gravatar",
    "yourdomain", "domain.tld", "email.com",
)
_BAD_TLDS = {"png", "jpg", "jpeg", "gif", "svg", "webp", "css", "js", "json", "ico"}
_GOOD_LOCALS = {
    "info", "mail", "hello", "contact", "contacts", "zakaz", "order",
    "welcome", "cafe", "rest", "restaurant", "bar", "food", "eda", "reception",
    "booking", "office", "msk", "moscow", "sales", "priem", "write",
}
_MAIL_HOSTS = {
    "gmail.com", "yandex.ru", "ya.ru", "mail.ru", "bk.ru", "inbox.ru",
    "list.ru", "rambler.ru", "outlook.com", "hotmail.com", "icloud.com",
    "yahoo.com", "proton.me", "protonmail.com",
}


def _valid_email(raw):
    address = raw.strip().lower().strip(".,;:()[]<>")
    if not re.fullmatch(_EMAIL_RE, address):
        return None
    local, _, domain = address.partition("@")
    if local in _BAD_LOCALS or local.startswith("noreply"):
        return None
    for bad in _BAD_DOMAIN_PARTS:
        if bad in domain:
            return None
    tld = domain.rsplit(".", 1)[-1]
    if tld in _BAD_TLDS:
        return None
    if re.match(r"^\d+x?$", domain.split(".")[0]):
        return None
    return address


def _domain_of(url):
    try:
        return (urlparse(url).hostname or "").lower().removeprefix("www.")
    except Exception:
        return ""


async def run(args, state):
    pages = list(state.get("pages") or [])
    banned = set()
    variables = dict(state.variables) if isinstance(state.variables, dict) else {}
    for raw in variables.get("banned_email_domains") or []:
        banned.add(str(raw).strip().lower())

    best = {}
    for page in pages:
        url = str(page.get("url") or "")
        text = str(page.get("text") or "")
        site_host = _domain_of(url)
        if not text:
            continue
        title = ""
        heading = re.search(_HEADING_RE, text, re.MULTILINE)
        if heading is not None:
            title = heading.group(1).strip()

        mailto_hits = {m.group(1).lower() for m in re.finditer(_MAILTO_RE, text, re.IGNORECASE)}
        found = set()
        for match in re.finditer(_EMAIL_RE, text):
            found.add(match.group(0))
        for match in re.finditer(_OBFUSCATED_RE, text, re.IGNORECASE):
            found.add(match.group(1) + "@" + match.group(2) + "." + match.group(3))

        contact_page = bool(_CONTACT_HIT_RE_search(url))
        for raw_email in found:
            email = _valid_email(raw_email)
            if email is None:
                continue
            _, _, mail_domain = email.partition("@")
            if mail_domain in banned:
                continue
            score = 1.0
            if email in mailto_hits:
                score += 2.0
            if contact_page:
                score += 1.0
            local = email.partition("@")[0]
            if local in _GOOD_LOCALS:
                score += 1.0
            if mail_domain == site_host or mail_domain.endswith("." + site_host) or site_host.endswith("." + mail_domain):
                score += 1.5
            elif mail_domain not in _MAIL_HOSTS:
                score -= 1.0
            lead = {
                "email": email,
                "business_name": "",
                "name_hint": title,
                "business_type": "",
                "source_url": url,
                "page_url": url,
                "site_domain": site_host,
                "confidence": round(score, 2),
            }
            prev = best.get(email)
            if prev is None or lead["confidence"] > prev["confidence"]:
                best[email] = lead

    leads = sorted(best.values(), key=lambda x: -x["confidence"])
    state["leads"] = leads
    state["leads_json"] = json.dumps(leads, ensure_ascii=False)
    return state


def _CONTACT_HIT_RE_search(url):
    return re.search(r"contact|kontakt|about|o-nas|feedback|svyaz", url, re.IGNORECASE)

