import json


async def run(args, state):
    leads = list(state.get("leads") or [])
    raw_response = state.get("response")
    if not isinstance(raw_response, str) or not raw_response.strip():
        raise ValueError("validate_leads: пустой ответ LLM")
    payload = json.loads(raw_response)
    verdicts = {}
    for item in payload.get("leads") or []:
        email = str(item.get("email") or "").strip().lower()
        if email:
            verdicts[email] = item

    kept = []
    rejected = []
    for lead in leads:
        verdict = verdicts.get(lead["email"])
        if verdict is None:
            lead["reject_reason"] = "llm_skip"
            rejected.append(lead)
            continue
        if verdict.get("keep") is not True:
            lead["reject_reason"] = str(verdict.get("reason") or "llm_reject")
            rejected.append(lead)
            continue
        name = str(verdict.get("business_name") or "").strip()
        lead["business_name"] = name or str(lead.get("name_hint") or "").strip()
        lead["business_type"] = str(verdict.get("business_type") or "other").strip()
        kept.append(lead)

    seeds = list(state.get("seed_leads") or [])
    if seeds and not leads:
        kept = seeds
    elif seeds:
        known = {item["email"] for item in kept}
        for seed in seeds:
            if seed["email"] not in known:
                kept.append(seed)

    state["leads"] = kept
    state["rejected_leads"] = rejected
    return state

